# ! [doc = " Candidate selection. See the [rustc dev guide] for more information on how this works."] # ! [doc = ""] # ! [doc = " [rustc dev guide]: https://rustc-dev-guide.rust-lang.org/traits/resolution.html#selection"] use split_decls_genesis :: ourprelude :: * ; use rustc_errors :: ErrorGuaranteed ; use rustc_hir :: def_id :: DefId ; use rustc_macros :: { HashStable , TypeVisitable } ; use rustc_query_system :: cache :: Cache ; use self :: EvaluationResult :: * ; use super :: { SelectionError , SelectionResult } ; use crate :: ty ; pub type SelectionCache < 'tcx , ENV > = Cache < (ENV , ty :: TraitPredicate < 'tcx >) , SelectionResult < 'tcx , SelectionCandidate < 'tcx > > > ; pub type EvaluationCache < 'tcx , ENV > = Cache < (ENV , ty :: PolyTraitPredicate < 'tcx >) , EvaluationResult > ; #[doc = " The selection process begins by considering all impls, where"] #[doc = " clauses, and so forth that might resolve an obligation. Sometimes"] #[doc = " we'll be able to say definitively that (e.g.) an impl does not"] #[doc = " apply to the obligation: perhaps it is defined for `usize` but the"] #[doc = " obligation is for `i32`. In that case, we drop the impl out of the"] #[doc = " list. But the other cases are considered *candidates*."] #[doc = ""] #[doc = " For selection to succeed, there must be exactly one matching"] #[doc = " candidate. If the obligation is fully known, this is guaranteed"] #[doc = " by coherence. However, if the obligation contains type parameters"] #[doc = " or variables, there may be multiple such impls."] #[doc = ""] #[doc = " It is not a real problem if multiple matching impls exist because"] #[doc = " of type variables - it just means the obligation isn't sufficiently"] #[doc = " elaborated. In that case we report an ambiguity, and the caller can"] #[doc = " try again after more type information has been gathered or report a"] #[doc = " \"type annotations needed\" error."] #[doc = ""] #[doc = " However, with type parameters, this can be a real problem - type"] #[doc = " parameters don't unify with regular types, but they *can* unify"] #[doc = " with variables from blanket impls, and (unless we know its bounds"] #[doc = " will always be satisfied) picking the blanket impl will be wrong"] #[doc = " for at least *some* generic parameters. To make this concrete, if"] #[doc = " we have"] #[doc = ""] #[doc = " ```rust, ignore"] #[doc = " trait AsDebug { type Out: fmt::Debug; fn debug(self) -> Self::Out; }"] #[doc = " impl<T: fmt::Debug> AsDebug for T {"] #[doc = "     type Out = T;"] #[doc = "     fn debug(self) -> fmt::Debug { self }"] #[doc = " }"] #[doc = " fn foo<T: AsDebug>(t: T) { println!(\"{:?}\", <T as AsDebug>::debug(t)); }"] #[doc = " ```"] #[doc = ""] #[doc = " we can't just use the impl to resolve the `<T as AsDebug>` obligation"] #[doc = " -- a type from another crate (that doesn't implement `fmt::Debug`) could"] #[doc = " implement `AsDebug`."] #[doc = ""] #[doc = " Because where-clauses match the type exactly, multiple clauses can"] #[doc = " only match if there are unresolved variables, and we can mostly just"] #[doc = " report this ambiguity in that case. This is still a problem - we can't"] #[doc = " *do anything* with ambiguities that involve only regions. This is issue"] #[doc = " #21974."] #[doc = ""] #[doc = " If a single where-clause matches and there are no inference"] #[doc = " variables left, then it definitely matches and we can just select"] #[doc = " it."] #[doc = ""] #[doc = " In fact, we even select the where-clause when the obligation contains"] #[doc = " inference variables. The can lead to inference making \"leaps of logic\","] #[doc = " for example in this situation:"] #[doc = ""] #[doc = " ```rust, ignore"] #[doc = " pub trait Foo<T> { fn foo(&self) -> T; }"] #[doc = " impl<T> Foo<()> for T { fn foo(&self) { } }"] #[doc = " impl Foo<bool> for bool { fn foo(&self) -> bool { *self } }"] #[doc = ""] #[doc = " pub fn foo<T>(t: T) where T: Foo<bool> {"] #[doc = "     println!(\"{:?}\", <T as Foo<_>>::foo(&t));"] #[doc = " }"] #[doc = " fn main() { foo(false); }"] #[doc = " ```"] #[doc = ""] #[doc = " Here the obligation `<T as Foo<$0>>` can be matched by both the blanket"] #[doc = " impl and the where-clause. We select the where-clause and unify `$0=bool`,"] #[doc = " so the program prints \"false\". However, if the where-clause is omitted,"] #[doc = " the blanket impl is selected, we unify `$0=()`, and the program prints"] #[doc = " \"()\"."] #[doc = ""] #[doc = " Exactly the same issues apply to projection and object candidates, except"] #[doc = " that we can have both a projection candidate and a where-clause candidate"] #[doc = " for the same obligation. In that case either would do (except that"] #[doc = " different \"leaps of logic\" would occur if inference variables are"] #[doc = " present), and we just pick the where-clause. This is, for example,"] #[doc = " required for associated types to work in default impls, as the bounds"] #[doc = " are visible both as projection bounds and as where-clauses from the"] #[doc = " parameter environment."] #[derive (PartialEq , Eq , Debug , Clone , TypeVisitable)] pub enum SelectionCandidate < 'tcx > { #[doc = " A built-in implementation for the `Sized` trait. This is preferred"] #[doc = " over all other candidates."] SizedCandidate , #[doc = " A builtin implementation for some specific traits, used in cases"] #[doc = " where we cannot rely an ordinary library implementations."] #[doc = ""] #[doc = " The most notable examples are `Copy` and `Clone`. This is also"] #[doc = " used for the `DiscriminantKind` and `Pointee` trait, both of which have"] #[doc = " an associated type."] BuiltinCandidate , #[doc = " Implementation of transmutability trait."] TransmutabilityCandidate , ParamCandidate (ty :: PolyTraitPredicate < 'tcx >) , ImplCandidate (DefId) , AutoImplCandidate , #[doc = " This is a trait matching with a projected type as `Self`, and we found"] #[doc = " an applicable bound in the trait definition. The `usize` is an index"] #[doc = " into the list returned by `tcx.item_bounds`."] ProjectionCandidate (usize) , #[doc = " Implementation of a `Fn`-family trait by one of the anonymous types"] #[doc = " generated for an `||` expression."] ClosureCandidate { is_const : bool , } , #[doc = " Implementation of an `AsyncFn`-family trait by one of the anonymous types"] #[doc = " generated for an `async ||` expression."] AsyncClosureCandidate , #[doc = " Implementation of the `AsyncFnKindHelper` helper trait, which"] #[doc = " is used internally to delay computation for async closures until after"] #[doc = " upvar analysis is performed in HIR typeck."] AsyncFnKindHelperCandidate , #[doc = " Implementation of a `Coroutine` trait by one of the anonymous types"] #[doc = " generated for a coroutine."] CoroutineCandidate , #[doc = " Implementation of a `Future` trait by one of the coroutine types"] #[doc = " generated for an async construct."] FutureCandidate , #[doc = " Implementation of an `Iterator` trait by one of the coroutine types"] #[doc = " generated for a `gen` construct."] IteratorCandidate , #[doc = " Implementation of an `AsyncIterator` trait by one of the coroutine types"] #[doc = " generated for a `async gen` construct."] AsyncIteratorCandidate , #[doc = " Implementation of a `Fn`-family trait by one of the anonymous"] #[doc = " types generated for a fn pointer type (e.g., `fn(int) -> int`)"] FnPointerCandidate , TraitAliasCandidate , #[doc = " Matching `dyn Trait` with a supertrait of `Trait`. The index is the"] #[doc = " position in the iterator returned by"] #[doc = " `rustc_infer::traits::util::supertraits`."] ObjectCandidate (usize) , #[doc = " Perform trait upcasting coercion of `dyn Trait` to a supertrait of `Trait`."] #[doc = " The index is the position in the iterator returned by"] #[doc = " `rustc_infer::traits::util::supertraits`."] TraitUpcastingUnsizeCandidate (usize) , BuiltinObjectCandidate , BuiltinUnsizeCandidate , BikeshedGuaranteedNoDropCandidate , } #[doc = " The result of trait evaluation. The order is important"] #[doc = " here as the evaluation of a list is the maximum of the"] #[doc = " evaluations."] #[doc = ""] #[doc = " The evaluation results are ordered:"] #[doc = "     - `EvaluatedToOk` implies `EvaluatedToOkModuloRegions`"] #[doc = "       implies `EvaluatedToAmbig` implies `EvaluatedToAmbigStackDependent`"] #[doc = "     - the \"union\" of evaluation results is equal to their maximum -"] #[doc = "     all the \"potential success\" candidates can potentially succeed,"] #[doc = "     so they are noops when unioned with a definite error, and within"] #[doc = "     the categories it's easy to see that the unions are correct."] #[derive (Copy , Clone , Debug , PartialOrd , Ord , PartialEq , Eq , HashStable)] pub enum EvaluationResult { #[doc = " Evaluation successful."] EvaluatedToOk , #[doc = " Evaluation successful, but there were unevaluated region obligations."] EvaluatedToOkModuloRegions , #[doc = " Evaluation successful, but need to rerun because opaque types got"] #[doc = " hidden types assigned without it being known whether the opaque types"] #[doc = " are within their defining scope"] EvaluatedToOkModuloOpaqueTypes , #[doc = " Evaluation is known to be ambiguous -- it *might* hold for some"] #[doc = " assignment of inference variables, but it might not."] #[doc = ""] #[doc = " While this has the same meaning as `EvaluatedToAmbigStackDependent` -- we can't"] #[doc = " know whether this obligation holds or not -- it is the result we"] #[doc = " would get with an empty stack, and therefore is cacheable."] EvaluatedToAmbig , #[doc = " Evaluation failed because of recursion involving inference"] #[doc = " variables. We are somewhat imprecise there, so we don't actually"] #[doc = " know the real result."] #[doc = ""] #[doc = " This can't be trivially cached because the result depends on the"] #[doc = " stack results."] EvaluatedToAmbigStackDependent , #[doc = " Evaluation failed."] EvaluatedToErr , } impl EvaluationResult { #[doc = " Returns `true` if this evaluation result is known to apply, even"] #[doc = " considering outlives constraints."] pub fn must_apply_considering_regions (self) -> bool { self == EvaluatedToOk } #[doc = " Returns `true` if this evaluation result is known to apply, ignoring"] #[doc = " outlives constraints."] pub fn must_apply_modulo_regions (self) -> bool { self <= EvaluatedToOkModuloRegions } pub fn may_apply (self) -> bool { match self { EvaluatedToOkModuloOpaqueTypes | EvaluatedToOk | EvaluatedToOkModuloRegions | EvaluatedToAmbig | EvaluatedToAmbigStackDependent => true , EvaluatedToErr => false , } } pub fn is_stack_dependent (self) -> bool { match self { EvaluatedToAmbigStackDependent => true , EvaluatedToOkModuloOpaqueTypes | EvaluatedToOk | EvaluatedToOkModuloRegions | EvaluatedToAmbig | EvaluatedToErr => false , } } } #[doc = " Indicates that trait evaluation caused overflow and in which pass."] #[derive (Copy , Clone , Debug , PartialEq , Eq , HashStable)] pub enum OverflowError { Error (ErrorGuaranteed) , Canonical , } impl From < ErrorGuaranteed > for OverflowError { fn from (e : ErrorGuaranteed) -> OverflowError { OverflowError :: Error (e) } } impl < 'tcx > From < OverflowError > for SelectionError < 'tcx > { fn from (overflow_error : OverflowError) -> SelectionError < 'tcx > { match overflow_error { OverflowError :: Error (e) => SelectionError :: Overflow (OverflowError :: Error (e)) , OverflowError :: Canonical => SelectionError :: Overflow (OverflowError :: Canonical) , } } }